-- MedKernel 全新上线数据库基线（PostgreSQL）
-- 本文件由 scripts/db/generate-migrations.mjs 根据 db/schema/medkernel.schema.json 生成，请勿手工修改。
-- 仅包含终态结构；固定职责、权限包与模型能力目录由应用代码播种。

CREATE TABLE audit_chain_head (
    tenant_id VARCHAR(64) NOT NULL,
    last_event_id VARCHAR(64),
    last_signature VARCHAR(512) NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE audit_event (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    event_id VARCHAR(64) NOT NULL,
    trace_id VARCHAR(128),
    occurred_at TIMESTAMP NOT NULL,
    actor_user_id VARCHAR(64),
    action VARCHAR(32) NOT NULL,
    resource_type VARCHAR(128) NOT NULL,
    resource_id VARCHAR(128) NOT NULL,
    summary VARCHAR(512),
    payload_digest VARCHAR(128),
    tenant_id VARCHAR(64) NOT NULL,
    hospital_id VARCHAR(64),
    department_id VARCHAR(64),
    ip_address VARCHAR(64),
    user_agent VARCHAR(512),
    signature VARCHAR(512),
    status VARCHAR(32) DEFAULT 'RECORDED' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    prev_event_id VARCHAR(64),
    prev_signature VARCHAR(512),
    outcome VARCHAR(16) DEFAULT 'SUCCESS' NOT NULL,
    error_code VARCHAR(64),
    actor_roles VARCHAR(512),
    org_path VARCHAR(1024),
    environment_key VARCHAR(64),
    before_snapshot TEXT,
    after_snapshot TEXT,
    dedupe_key VARCHAR(128)
);

CREATE TABLE canonical_resource (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    resource_id VARCHAR(64) NOT NULL,
    snapshot_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    resource_type VARCHAR(32) NOT NULL,
    resource_payload TEXT NOT NULL,
    source_system VARCHAR(64),
    source_record_id VARCHAR(128),
    mapped_version VARCHAR(64),
    event_time TIMESTAMP,
    received_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    quality_status VARCHAR(32) DEFAULT 'VALID' NOT NULL,
    seq_no INTEGER DEFAULT 0 NOT NULL,
    trace_id VARCHAR(128)
);

CREATE TABLE citation (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    asset_version_id BIGINT NOT NULL,
    source_fragment_id BIGINT NOT NULL,
    relation VARCHAR(32) DEFAULT 'DERIVED_FROM' NOT NULL,
    weight INTEGER DEFAULT 100 NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    start_offset INTEGER,
    end_offset INTEGER
);

CREATE TABLE clinical_clock (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    clock_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    patient_pathway_id VARCHAR(64) NOT NULL,
    node_code VARCHAR(128) NOT NULL,
    metric_code VARCHAR(128),
    started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    due_at TIMESTAMP,
    completed_at TIMESTAMP,
    status VARCHAR(32) DEFAULT 'RUNNING' NOT NULL,
    baseline_event VARCHAR(64),
    baseline_at TIMESTAMP,
    min_due_at TIMESTAMP,
    target_due_at TIMESTAMP,
    max_due_at TIMESTAMP,
    escalation_level VARCHAR(32) DEFAULT 'NONE' NOT NULL,
    escalation_policy_json TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    trace_id VARCHAR(128)
);

CREATE TABLE clinical_runtime_release (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    release_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    hospital_id VARCHAR(64) NOT NULL,
    revision_no BIGINT NOT NULL,
    platform_baseline_release_id VARCHAR(64) NOT NULL,
    manifest_sha256 VARCHAR(64) NOT NULL,
    rollback_from_release_id VARCHAR(64),
    activated_at TIMESTAMP NOT NULL,
    activated_by VARCHAR(64) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    trace_id VARCHAR(128)
);

CREATE TABLE clinical_event (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    event_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    event_type VARCHAR(32) NOT NULL,
    source_system VARCHAR(64),
    payload_digest VARCHAR(128),
    occurred_at TIMESTAMP NOT NULL,
    received_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    snapshot_id VARCHAR(64),
    processing_status VARCHAR(32) DEFAULT 'RECEIVED' NOT NULL,
    trace_id VARCHAR(128),
    patient_id VARCHAR(64),
    encounter_id VARCHAR(64),
    clinical_setting VARCHAR(16) NOT NULL,
    runtime_release_id VARCHAR(64) NOT NULL,
    error_code VARCHAR(64),
    error_class VARCHAR(32),
    retry_count INTEGER DEFAULT 0 NOT NULL,
    root_event_id VARCHAR(64),
    org_scope_json TEXT,
    trigger_point VARCHAR(64),
    idempotency_key VARCHAR(128),
    callback_webhook_id VARCHAR(64)
);

CREATE TABLE clinical_event_outbox (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    event_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    trace_id VARCHAR(128),
    actor_user_id VARCHAR(64),
    claim_status VARCHAR(16) DEFAULT 'PENDING' NOT NULL,
    claimed_by VARCHAR(64),
    claimed_at TIMESTAMP,
    next_attempt_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    retry_count INTEGER DEFAULT 0 NOT NULL,
    last_error_code VARCHAR(64),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    processed_at TIMESTAMP
);

CREATE TABLE clinical_event_payload (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    event_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    payload TEXT,
    payload_uri VARCHAR(256),
    storage_type VARCHAR(16) DEFAULT 'INLINE' NOT NULL,
    content_type VARCHAR(64) DEFAULT 'application/json' NOT NULL,
    digest VARCHAR(128) NOT NULL,
    size_bytes BIGINT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted_at TIMESTAMP
);

CREATE TABLE context_idempotency_key (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    idem_key VARCHAR(128) NOT NULL,
    snapshot_id VARCHAR(64) NOT NULL,
    payload_digest VARCHAR(128) NOT NULL,
    expires_at TIMESTAMP NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE context_snapshot (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    snapshot_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    org_unit_id VARCHAR(64) NOT NULL,
    patient_id VARCHAR(64) NOT NULL,
    encounter_id VARCHAR(64),
    runtime_release_id VARCHAR(64) NOT NULL,
    status VARCHAR(32) DEFAULT 'ACTIVE' NOT NULL,
    missing_fields TEXT,
    mapping_status TEXT,
    extensions_json TEXT NOT NULL,
    quality_status VARCHAR(32) DEFAULT 'VALID' NOT NULL,
    trace_id VARCHAR(128),
    signature VARCHAR(512),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    request_id VARCHAR(128),
    org_path VARCHAR(512)
);

CREATE TABLE embed_launch_token (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    token VARCHAR(128) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    user_id VARCHAR(64) NOT NULL,
    role_code VARCHAR(64) NOT NULL,
    patient_id VARCHAR(64) NOT NULL,
    encounter_id VARCHAR(64) NOT NULL,
    trigger_point VARCHAR(64) NOT NULL,
    status VARCHAR(32) DEFAULT 'UNUSED' NOT NULL,
    expired_at TIMESTAMP NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    trace_id VARCHAR(128),
    integration_mode VARCHAR(16) DEFAULT 'IFRAME' NOT NULL,
    hook VARCHAR(64),
    hook_instance VARCHAR(128),
    consumed_at TIMESTAMP,
    parent_origin VARCHAR(512)
);

CREATE TABLE embed_origin_whitelist (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    origin VARCHAR(255) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL
);

CREATE TABLE emergency_permission_grant (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    user_id VARCHAR(128) NOT NULL,
    permission_code VARCHAR(128) DEFAULT 'env.emergency' NOT NULL,
    reason VARCHAR(512) NOT NULL,
    granted_by VARCHAR(128) NOT NULL,
    granted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    expires_at TIMESTAMP NOT NULL,
    revoked_at TIMESTAMP,
    revoked_by VARCHAR(128),
    active_flag CHAR(1) DEFAULT 'Y' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL
);

CREATE TABLE evaluation_idempotency_key (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    idem_key VARCHAR(128) NOT NULL,
    operation_type VARCHAR(32) NOT NULL,
    finding_id VARCHAR(64) NOT NULL,
    task_id VARCHAR(64) NOT NULL,
    review_id VARCHAR(64),
    request_digest VARCHAR(128) NOT NULL,
    finding_status VARCHAR(32) NOT NULL,
    task_status VARCHAR(32) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    trace_id VARCHAR(128)
);

CREATE TABLE evaluation_indicator (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    indicator_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    indicator_code VARCHAR(128) NOT NULL,
    version_no INTEGER NOT NULL,
    name VARCHAR(256) NOT NULL,
    subject_type VARCHAR(32) NOT NULL,
    denominator_definition TEXT NOT NULL,
    numerator_definition TEXT NOT NULL,
    exclusion_definition TEXT,
    scoring_definition TEXT,
    time_window VARCHAR(128) NOT NULL,
    organization_scope VARCHAR(256) NOT NULL,
    responsible_department_id VARCHAR(64) NOT NULL,
    source_ref VARCHAR(512) NOT NULL,
    status VARCHAR(32) DEFAULT 'DRAFT' NOT NULL,
    published_at TIMESTAMP,
    published_by VARCHAR(64),
    activated_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    trace_id VARCHAR(128)
);

CREATE TABLE evaluation_result (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    result_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    run_id VARCHAR(64) NOT NULL,
    indicator_id VARCHAR(64) NOT NULL,
    indicator_code VARCHAR(128) NOT NULL,
    indicator_version INTEGER NOT NULL,
    subject_type VARCHAR(32) NOT NULL,
    subject_ref_id VARCHAR(128) NOT NULL,
    score_value NUMERIC(18,4),
    result_level VARCHAR(32) NOT NULL,
    hit_flag BOOLEAN DEFAULT FALSE NOT NULL,
    evidence_summary VARCHAR(2048) NOT NULL,
    source_ref VARCHAR(512),
    responsible_department_id VARCHAR(64),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    trace_id VARCHAR(128)
);

CREATE TABLE evaluation_run (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    run_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    run_code VARCHAR(128) NOT NULL,
    run_type VARCHAR(32) NOT NULL,
    source_event_id VARCHAR(64),
    context_snapshot_id VARCHAR(64),
    patient_id VARCHAR(128),
    encounter_id VARCHAR(128),
    scenario_code VARCHAR(128) NOT NULL,
    runtime_release_id VARCHAR(64),
    input_digest VARCHAR(128) NOT NULL,
    status VARCHAR(32) DEFAULT 'RECEIVED' NOT NULL,
    error_code VARCHAR(64),
    occurred_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    trace_id VARCHAR(128)
);

CREATE TABLE evidence_snapshot (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    evidence_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    trace_id VARCHAR(128),
    evidence_type VARCHAR(64) NOT NULL,
    action VARCHAR(32) NOT NULL,
    subject_type VARCHAR(128) NOT NULL,
    subject_id VARCHAR(64) NOT NULL,
    evidence_summary VARCHAR(512) NOT NULL,
    payload_snapshot VARCHAR(4000) NOT NULL,
    payload_hash VARCHAR(128) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    file_uri VARCHAR(512),
    file_digest VARCHAR(128),
    signature_algorithm VARCHAR(32),
    signature_value VARCHAR(2048),
    signer_public_key VARCHAR(2048)
);

CREATE TABLE followup_event (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    event_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    plan_id VARCHAR(64),
    event_type VARCHAR(32) NOT NULL,
    payload TEXT NOT NULL,
    triggered_by VARCHAR(64),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    trace_id VARCHAR(128),
    idempotency_key VARCHAR(128)
);

CREATE TABLE followup_plan (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    plan_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    patient_id VARCHAR(64) NOT NULL,
    encounter_id VARCHAR(64),
    pathway_id VARCHAR(64),
    disease_code VARCHAR(128),
    risk_level VARCHAR(32),
    runtime_release_id VARCHAR(64),
    status VARCHAR(32) DEFAULT 'DRAFT' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    trace_id VARCHAR(128),
    idempotency_key VARCHAR(128),
    source_fact_type VARCHAR(32),
    source_fact_id VARCHAR(128),
    generation_rule_code VARCHAR(96),
    generation_explanation TEXT,
    template_id VARCHAR(64),
    template_version INTEGER
);

CREATE TABLE followup_questionnaire (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    questionnaire_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    task_id VARCHAR(64) NOT NULL,
    form_data TEXT NOT NULL,
    score NUMERIC(10,2),
    status VARCHAR(32) DEFAULT 'DRAFT' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    trace_id VARCHAR(128),
    plan_id VARCHAR(64),
    questionnaire_template_id VARCHAR(128),
    answer_data TEXT,
    idempotency_key VARCHAR(128),
    submitted_at TIMESTAMP,
    executor_id VARCHAR(64)
);

CREATE TABLE followup_task (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    task_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    plan_id VARCHAR(64) NOT NULL,
    task_type VARCHAR(32) NOT NULL,
    due_date TIMESTAMP NOT NULL,
    status VARCHAR(32) DEFAULT 'PENDING' NOT NULL,
    executor_id VARCHAR(64),
    executor_type VARCHAR(32),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    trace_id VARCHAR(128),
    idempotency_key VARCHAR(128),
    clinical_clock_id VARCHAR(64),
    questionnaire_template_id VARCHAR(128)
);

CREATE TABLE integration_adapter (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    adapter_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    name VARCHAR(256) NOT NULL,
    protocol_type VARCHAR(64) NOT NULL,
    status VARCHAR(32) DEFAULT 'ACTIVE' NOT NULL,
    config_json VARCHAR(4000),
    health_status VARCHAR(32) DEFAULT 'HEALTHY' NOT NULL,
    rtt_ms BIGINT DEFAULT 0 NOT NULL,
    last_heartbeat_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL
);

CREATE TABLE integration_message_log (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    message_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    trace_id VARCHAR(128),
    direction VARCHAR(32) NOT NULL,
    system_name VARCHAR(128) NOT NULL,
    protocol_type VARCHAR(32) NOT NULL,
    payload_summary VARCHAR(512),
    payload VARCHAR(4000),
    status VARCHAR(32) DEFAULT 'SUCCESS' NOT NULL,
    retry_count INTEGER DEFAULT 0 NOT NULL,
    max_retries INTEGER DEFAULT 3 NOT NULL,
    error_message VARCHAR(512),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL
);

CREATE TABLE integration_webhook_config (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    webhook_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    name VARCHAR(256) NOT NULL,
    callback_url VARCHAR(512) NOT NULL,
    secret_cipher VARCHAR(256) NOT NULL,
    events_subscribed VARCHAR(512) NOT NULL,
    status VARCHAR(32) DEFAULT 'ACTIVE' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL
);

CREATE TABLE knowledge_asset_version (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    identity_id BIGINT NOT NULL,
    version_no VARCHAR(64) NOT NULL,
    version_label VARCHAR(256),
    source_document_id BIGINT,
    source_version_id BIGINT,
    content_hash VARCHAR(128) NOT NULL,
    anchors VARCHAR(2048),
    status VARCHAR(32) DEFAULT 'DRAFT' NOT NULL,
    risk_level VARCHAR(16) DEFAULT 'MEDIUM' NOT NULL,
    effective_from TIMESTAMP,
    effective_to TIMESTAMP,
    reviewed_by VARCHAR(64),
    reviewed_at TIMESTAMP,
    activated_at TIMESTAMP,
    superseded_at TIMESTAMP,
    withdrawn_at TIMESTAMP,
    withdrawn_reason VARCHAR(512),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    authority_level VARCHAR(32),
    grade_quality VARCHAR(16),
    grade_strength VARCHAR(16),
    conflict_arbitration VARCHAR(2048),
    organization_scope VARCHAR(256) NOT NULL,
    applicable_scope VARCHAR(256) NOT NULL,
    active_scope_key VARCHAR(768) NOT NULL,
    review_cycle_months INTEGER DEFAULT 12 NOT NULL,
    next_review_at TIMESTAMP
);

CREATE TABLE knowledge_export_job (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    job_code VARCHAR(64) NOT NULL,
    requested_by VARCHAR(64) NOT NULL,
    export_type VARCHAR(32) NOT NULL,
    filter_json VARCHAR(2048),
    status VARCHAR(32) DEFAULT 'PENDING' NOT NULL,
    progress INTEGER DEFAULT 0 NOT NULL,
    result_uri VARCHAR(512),
    item_count BIGINT,
    error_message VARCHAR(1024),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    started_at TIMESTAMP,
    completed_at TIMESTAMP,
    expires_at TIMESTAMP
);

CREATE TABLE knowledge_identity (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    identity_code VARCHAR(128) NOT NULL,
    domain VARCHAR(32) NOT NULL,
    subject VARCHAR(512) NOT NULL,
    specialty_id VARCHAR(64),
    description VARCHAR(2048),
    status VARCHAR(32) DEFAULT 'ACTIVE' NOT NULL,
    current_version_id BIGINT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL
);

CREATE TABLE knowledge_supersession (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    identity_id BIGINT NOT NULL,
    old_version_id BIGINT,
    new_version_id BIGINT,
    transition_type VARCHAR(32) NOT NULL,
    transition_reason VARCHAR(512),
    transitioned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    transitioned_by VARCHAR(64) NOT NULL,
    successor_identity_id BIGINT,
    grace_period_end TIMESTAMP,
    migration_guidance VARCHAR(1000)
);

CREATE TABLE local_term (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    source_system VARCHAR(64) NOT NULL,
    local_code VARCHAR(128) NOT NULL,
    category VARCHAR(32) NOT NULL,
    local_name VARCHAR(512) NOT NULL,
    normalized_name VARCHAR(512),
    department_id VARCHAR(64),
    status VARCHAR(32) DEFAULT 'UNMAPPED' NOT NULL,
    first_seen_at TIMESTAMP,
    last_seen_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL
);

CREATE TABLE mapping_candidate (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    local_term_id BIGINT NOT NULL,
    standard_term_id BIGINT NOT NULL,
    confidence DOUBLE PRECISION,
    candidate_source VARCHAR(32) DEFAULT 'RULE' NOT NULL,
    risk_level VARCHAR(16) DEFAULT 'MEDIUM' NOT NULL,
    evidence_text VARCHAR(1024),
    conflict_flag BOOLEAN DEFAULT FALSE NOT NULL,
    status VARCHAR(32) DEFAULT 'PENDING' NOT NULL,
    review_note VARCHAR(500),
    reviewed_by VARCHAR(64),
    reviewed_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    generation_job_code VARCHAR(64)
);

CREATE TABLE mapping_conflict (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    conflict_type VARCHAR(32) NOT NULL,
    local_term_id BIGINT,
    standard_term_id BIGINT,
    mapping_id BIGINT,
    risk_level VARCHAR(16) DEFAULT 'MEDIUM' NOT NULL,
    description VARCHAR(1024) NOT NULL,
    status VARCHAR(32) DEFAULT 'OPEN' NOT NULL,
    resolved_by VARCHAR(64),
    resolved_at TIMESTAMP,
    resolution_note VARCHAR(500),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64) DEFAULT 'system' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) DEFAULT 'system' NOT NULL
);

CREATE TABLE mk_aik_gate_result (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    job_code VARCHAR(64) NOT NULL,
    content_hash VARCHAR(64) NOT NULL,
    gate_code VARCHAR(48) NOT NULL,
    passed BOOLEAN NOT NULL,
    reason VARCHAR(512),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by VARCHAR(64)
);

CREATE TABLE mk_clinical_care_plan (
    care_plan_id VARCHAR(64) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    org_path VARCHAR(512) NOT NULL,
    source_system VARCHAR(64) NOT NULL,
    source_id VARCHAR(128) NOT NULL,
    fhir_resource_id VARCHAR(128),
    patient_id VARCHAR(64) NOT NULL,
    encounter_id VARCHAR(64),
    pathway_id VARCHAR(64),
    status VARCHAR(32),
    created_at TIMESTAMP NOT NULL,
    created_by VARCHAR(64) NOT NULL,
    updated_at TIMESTAMP NOT NULL,
    updated_by VARCHAR(64) NOT NULL,
    trace_id VARCHAR(128)
);

CREATE TABLE mk_clinical_claim (
